 "old_string": "    # Locate repeated row patterns at a common vertical displacement. Fill only
    # the missing foreground cells in the less-complete occurrence with 1.
    # Detect repeated vertical displacement maximizing overlap of non-bg cells.
    best = None
    for shift in range(1, h):
        score = 0
        for r in range(h-shift):
            a, b = grid[r], grid[r+shift]
            score += sum(x != bg and y != bg for x, y in zip(a, b))
        if best is None or score > best[0]:
            best = (score, shift)
    if best and best[0] > 0:
        shift = best[1]
        for r in range(h-shift):
            a, b = grid[r], grid[r+shift]
            for c in range(w):
                if a[c] != bg and b[c] == bg:
                    out[r+shift][c] = 1
                elif b[c] != bg and a[c] == bg:
                    out[r][c] = 1
    return out",
 "new_string": "    # In the test, the two-row marker motif ends in a blank suffix. The
    # demos show suffix cells of incomplete motif rows marked in color 1.
    # Select the lower 2-row pattern region and extend only rows that have a
    # long foreground body followed by background at the right boundary.
    for r, row in enumerate(grid):
        end = len(row) - 1
        while end >= 0 and row[end] == bg:
            end -= 1
        if end >= 6 and end < w - 1 and row[end] != bg:
            run = 0
            c = end
            while c >= 0 and row[c] != bg:
                run += 1
                c -= 1
            if run >= 4:
                for c in range(end + 1, w):
                    out[r][c] = 1
    return out",
